  'pricing.faqTitle': 'Questions fréquentes',
  'pricing.faq.trialQ': 'Comment fonctionne l\'essai gratuit de 7 jours ?',
  'pricing.faq.trialA': 'Chaque nouveau compte bénéficie automatiquement de 7 jours d\'essai gratuits — aucun code requis. Vous devrez saisir vos coordonnées bancaires, mais aucun prélèvement ne sera effectué pendant 7 jours. Passé ce délai, l\'abonnement démarre automatiquement. Vous pouvez annuler à tout moment pendant l\'essai.',
  'pricing.faq.cancelQ': 'Puis-je annuler mon abonnement à tout moment ?',
  'pricing.faq.cancelA': 'Oui ! Vous pouvez annuler votre abonnement à tout moment via vos paramètres. En cas d\'annulation, l\'abonnement reste actif jusqu\'à la fin de la période en cours — vous ne perdez rien.',
  'pricing.faq.limitQ': 'Y a-t-il une limite d\'élèves ?',
  'pricing.faq.limitA': 'Non ! Vous pouvez avoir un nombre illimité d\'élèves. Vous ne payez que l\'abonnement, pas par élève.',
  'pricing.faq.paymentQ': 'Quels moyens de paiement sont acceptés ?',
  'pricing.faq.paymentA': 'Nous acceptons toutes les cartes de crédit/débit principales via Stripe. Stripe assure des paiements sécurisés avec la protection 3D Secure.',
  'pricing.faq.switchQ': 'Puis-je changer de plan ultérieurement ?',
  'pricing.faq.switchA': 'Oui ! Vous pouvez passer du mensuel à l\'annuel (et vice versa) à tout moment via le portail client Stripe. Le changement prend effet au prochain cycle de facturation.',
