  'landing.footerCompany': 'Entreprise',
  'landing.faq.whatIsQ': 'Qu\'est-ce que Tutlio ?',
  'landing.faq.whatIsA': 'Tutlio est une plateforme de gestion de cours particuliers qui aide les tuteurs privés et les écoles à gérer les horaires, les paiements, la communication avec les élèves et l\'historique des cours en un seul endroit.',
  'landing.faq.whoForQ': 'À qui s\'adresse Tutlio ?',
  'landing.faq.whoForA': 'Tutlio est conçu pour les tuteurs privés, les professeurs de musique, les professeurs de langues, les tuteurs en mathématiques, les écoles de tutorat et les centres éducatifs.',
  'landing.faq.waitlistQ': 'Comment fonctionne la liste d\'attente ?',
  'landing.faq.waitlistA': 'Lorsqu\'un élève annule un cours, le créneau libéré est automatiquement proposé aux élèves en liste d\'attente. Le premier à confirmer obtient la place.',
  'landing.faq.freeTrialQ': 'Y a-t-il un essai gratuit ?',
  'landing.faq.freeTrialA': 'Oui ! Chaque nouveau compte bénéficie automatiquement de 7 jours gratuits — aucun code requis. Aucun frais pendant la période d\'essai.',
  'landing.faq.languagesQ': 'Quelles langues sont supportées ?',
  'landing.faq.languagesA': 'Tutlio est disponible en 12 langues : lituanien, anglais, polonais, letton, estonien, français, espagnol, allemand, suédois, danois, finnois et norvégien.',
  'landing.faqTitle': 'Questions fréquemment posées',
  'feature.calendar.pageTitle': 'Calendrier intelligent pour tuteurs et logiciel de planification',
  'feature.calendar.pageDesc': 'Laissez les élèves réserver eux-mêmes des cours à partir de vos créneaux disponibles. Le calendrier intelligent de Tutlio gère automatiquement les cours récurrents, les pauses et les délais de réservation.',
  'feature.calendar.detailsTitle': 'Comment fonctionne le calendrier intelligent',
  'feature.calendar.selfBooking': 'Réservation en libre-service',
  'feature.calendar.selfBookingDesc': 'Définissez vos créneaux disponibles et laissez les élèves réserver directement.',
  'feature.calendar.recurring': 'Cours récurrents',
  'feature.calendar.recurringDesc': 'Créez des cours hebdomadaires ou bihebdomadaires récurrents qui apparaissent automatiquement dans les deux calendriers.',
  'feature.calendar.breaks': 'Gestion des pauses',
  'feature.calendar.breaksDesc': 'Configurez des pauses automatiques entre les cours.',
  'feature.calendar.deadlines': 'Délais de réservation',
  'feature.calendar.deadlinesDesc': 'Définissez le délai de réservation à l\'avance (par exemple, 24 heures avant).',
  'feature.calendar.faq.howBookQ': 'Comment les élèves réservent-ils ?',
  'feature.calendar.faq.howBookA': 'Les élèves reçoivent un lien de réservation personnel où ils voient vos créneaux disponibles et peuvent réserver directement.',
  'feature.calendar.faq.groupLessonsQ': 'Puis-je planifier des cours de groupe ?',
  'feature.calendar.faq.groupLessonsA': 'Oui ! Vous pouvez créer des créneaux de cours de groupe.',
  'feature.calendar.faq.mobileCalendarQ': 'Le calendrier fonctionne-t-il sur mobile ?',
  'feature.calendar.faq.mobileCalendarA': 'Oui, Tutlio fonctionne sur tout appareil — ordinateur, tablette ou téléphone.',
  'feature.waitlist.pageTitle': 'Liste d\'attente — ne perdez plus de revenus suite aux annulations',
  'feature.waitlist.pageDesc': 'Quand un élève annule, Tutlio propose automatiquement le créneau libéré aux élèves en liste d\'attente.',
  'feature.waitlist.detailsTitle': 'Comment fonctionne la liste d\'attente',
  'feature.waitlist.autoFill': 'Remplissage automatique des créneaux',
  'feature.waitlist.autoFillDesc': 'Quand un cours est annulé, le système notifie instantanément les élèves en liste d\'attente.',
  'feature.waitlist.notifications': 'Notifications instantanées',
  'feature.waitlist.notificationsDesc': 'Les élèves en liste d\'attente reçoivent des notifications e-mail instantanées quand leur créneau préféré se libère.',
  'feature.waitlist.priority': 'File d\'attente prioritaire',
  'feature.waitlist.priorityDesc': 'Les élèves rejoignent la liste d\'attente pour des créneaux spécifiques. La file assure un accès équitable.',
  'feature.waitlist.revenue': 'Protection des revenus',
  'feature.waitlist.revenueDesc': 'Arrêtez de perdre des revenus à cause des annulations. La liste d\'attente garantit un remplissage rapide.',
  'feature.waitlist.faq.howWorksQ': 'Comment la liste d\'attente remplit-elle les créneaux annulés ?',
  'feature.waitlist.faq.howWorksA': 'Quand un élève annule, le système vérifie la liste d\'attente et envoie une offre. Le premier à confirmer obtient le cours.',
  'feature.waitlist.faq.studentLimitQ': 'Y a-t-il une limite d\'élèves en liste d\'attente ?',
  'feature.waitlist.faq.studentLimitA': 'Non, il n\'y a pas de limite.',
  'feature.waitlist.faq.automaticQ': 'Le processus est-il entièrement automatique ?',
  'feature.waitlist.faq.automaticA': 'Oui ! Une fois configuré, tout le flux est entièrement automatisé.',
  'feature.payments.pageTitle': 'Traitement des paiements et facturation pour tuteurs',
  'feature.payments.pageDesc': 'Acceptez les paiements des élèves via Stripe, suivez qui a payé, générez des factures et consultez les résumés mensuels.',
  'feature.payments.detailsTitle': 'Fonctionnalités de paiement',
  'feature.payments.stripe': 'Intégration Stripe',
  'feature.payments.stripeDesc': 'Acceptez les paiements par carte de crédit et de débit en toute sécurité via Stripe avec protection 3D Secure intégrée.',
  'feature.payments.tracking': 'Suivi des paiements',
  'feature.payments.trackingDesc': 'Voyez d\'un coup d\'œil quels élèves ont payé, quels paiements sont en attente et lesquels sont en retard.',
  'feature.payments.invoices': 'Génération de factures',
  'feature.payments.invoicesDesc': 'Générez des factures professionnelles et envoyez-les directement par e-mail.',
  'feature.payments.packages': 'Forfaits de cours',
  'feature.payments.packagesDesc': 'Vendez des forfaits de cours (par exemple, 10 cours avec réduction) et suivez l\'utilisation automatiquement.',
  'feature.payments.faq.methodsQ': 'Quels modes de paiement sont acceptés ?',
  'feature.payments.faq.methodsA': 'Tutlio utilise Stripe, qui accepte toutes les principales cartes de crédit et de débit, Apple Pay, Google Pay et les virements bancaires.',
  'feature.payments.faq.feesQ': 'Tutlio facture-t-il des frais supplémentaires ?',
  'feature.payments.faq.feesA': 'Tutlio ne facture pas de frais supplémentaires. Les frais standard de Stripe s\'appliquent.',
  'feature.payments.faq.invoiceAutoQ': 'Les factures peuvent-elles être générées automatiquement ?',
  'feature.payments.faq.invoiceAutoA': 'Oui, vous pouvez générer des factures par élève ou par période.',
  'feature.reminders.pageTitle': 'Rappels automatiques de cours pour tuteurs',
  'feature.reminders.pageDesc': 'Envoyez des rappels automatiques par e-mail avant les cours, des suivis après les séances et des notifications de paiements en retard.',
  'feature.reminders.detailsTitle': 'Types de rappels',
  'feature.reminders.beforeLesson': 'Rappels avant le cours',
